## Why This Is Asked
Tests ability to blend topological ordering with DP to compute the longest-path in a weighted DAG and count the number of critical paths, including multiple sources and modulo arithmetic.

## Key Concepts
- Longest-path in DAG with node durations and edge setup weights
- Topological sort (Kahn) to process in dependency order
- DP for counting number of longest paths with modulo

## Code Example
```javascript
function countCriticalPaths(N, edges, dur) {
  const MOD = 1000000007;
  const incoming = Array.from({length: N}, () => []);
  const indeg = Array(N).fill(0);

  for (const [u, v, w] of edges) {
    incoming[v].push([u, w]);
    indeg[v]++;
  }

  const EFT = dur.slice();
  const count = Array(N).fill(0);
  const q = [];

  for (let i = 0; i < N; i++) {
    if (indeg[i] === 0) {
      count[i] = 1;
      q.push(i);
    }
  }

  while (q.length) {
    const u = q.shift();
    for (const [v, w] of incoming[u]) {
      const newEFT = EFT[u] + w + dur[v];
      if (newEFT > EFT[v]) {
        EFT[v] = newEFT;
        count[v] = count[u];
      } else if (newEFT === EFT[v]) {
        count[v] = (count[v] + count[u]) % MOD;
      }
      indeg[u]--;
      if (indeg[u] === 0) q.push(u);
    }
  }

  let maxEFT = 0, totalCritical = 0;
  for (let i = 0; i < N; i++) {
    if (EFT[i] > maxEFT) {
      maxEFT = EFT[i];
      totalCritical = count[i];
    } else if (EFT[i] === maxEFT) {
      totalCritical = (totalCritical + count[i]) % MOD;
    }
  }
  return { EFT, maxEFT, criticalPaths: totalCritical };
}
```

## Complexity
- Time: O(N + M) for topological sort and DP
- Space: O(N + M) for adjacency and arrays

## Why This Is Asked
Tests data-structure augmentation in a Trie to support prefix queries and k-th item retrieval with weights, mirroring autocomplete and ranking systems.

## Key Concepts
- Trie augmentation with per-subtree weights
- Prefix sum queries in O(length of prefix)
- K-th word selection within a prefix using cumulative weights
- Handling duplicates and deletions robustly

## Code Example
```javascript
class TrieNode { constructor(){ this.next=new Map(); this.subWeight=0; this.endWeight=0; this.isWord=false; } }
class Trie {
  constructor(){ this.root=new TrieNode(); }
  insert(word,w){ let node=this.root; node.subWeight+=w; for(let ch of word){ if(!node.next.has(ch)) node.next.set(ch,new TrieNode()); node=node.next.get(ch); node.subWeight+=w; } node.isWord=true; node.endWeight+=w; }
  delete(word,w){ this.insert(word,-w); }
  sumPrefix(prefix){ let node=this.root; for(let ch of prefix){ if(!node.next.has(ch)) return 0; node=node.next.get(ch); } return node.subWeight; }
  kthWord(prefix,k){ let node=this.root; for(let ch of prefix){ if(!node.next.has(ch)) return null; node=node.next.get(ch); }
    function dfs(n, path){ if(n.isWord && n.endWeight>0){ if(--k===0) return path; }
      for(let c of [...n.next.keys()].sort()){ let child=n.next.get(c); if(child.subWeight>=k){ const res=dfs(child, path+c); if(res) return res; } else { k-=child.subWeight; } }
      return null; }
    return dfs(node, prefix);
  }
}
```

